"  <!-- Core Storage & Reusable Navigation Script -->
  <script src="scripts/db.js"></script>
  <script src="components/navbar.js"></script>

  <!-- HUD Telemetry Controller -->
  <script>
    function updateHUDCountdowns() {
      const targetDate = new Date('2027-01-24T09:00:00+05:30').getTime();
      const now = Date.now();
      const diff = targetDate - now;

      if (diff > 0) {
        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
        const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
        const mins = Math.floor((diff / (1000 * 60)) % 60);
        const secs = Math.floor((diff / 1000) % 60);

        const daysEl = document.getElementById('hud-jee-days');
        const secsEl = document.getElementById('hud-jee-secs');

        if (daysEl) daysEl.innerText = `${days}d ${hours}h ${mins}m`;
        if (secsEl) secsEl.innerText = `${secs}s remaining until Session 1`;
      }
    }

    async function loadFocusProgress() {
      if (window.ClockEEDB) {
        try {
          const sessions = await ClockEEDB.getAll('sessions');
          let totalMins = 0;
          const today = new Date().toDateString();
          sessions.forEach(s => {
            if (s.timestamp && new Date(s.timestamp).toDateString() === today) {
              totalMins += (s.durationMinutes || 0);
            }
          });
          if (totalMins > 0) {
            const hours = (totalMins / 60).toFixed(1);
            const el = document.getElementById('hud-focus-hours');
            if (el) el.innerHTML = `${hours} <span class="text-sm font-semibold text-slate-400">/ 8.0h</span>`;
          }
        } catch(e) {
          console.warn('Could not read sessions from DB:', e);
        }
      }
    }

    updateHUDCountdowns();
    setInterval(updateHUDCountdowns, 1000);
    window.addEventListener('DOMContentLoaded', loadFocusProgress);
  </script>"

