"const fs = require('fs');
const path = require('path');

const htmlFiles = fs.readdirSync('.').filter(f => f.endsWith('.html'));
const results = {};

htmlFiles.forEach(file => {
  const content = fs.readFileSync(file, 'utf8');
  const missing = [];

  const srcMatches = content.matchAll(/src=["']([^"']+)["']/g);
  for (const match of srcMatches) {
    const url = match[1];
    if (!url.startsWith('http') && !url.startsWith('data:') && !url.startsWith('blob:')) {
      const cleanPath = url.split('?')[0].split('#')[0];
      if (!fs.existsSync(cleanPath) && cleanPath !== 'env.js') {
        missing.push({ type: 'script', path: cleanPath });
      }
    }
  }

  const hrefMatches = content.matchAll(/<link[^>]+href=["']([^"']+)["']/g);
  for (const match of hrefMatches) {
    const url = match[1];
    if (!url.startsWith('http') && !url.startsWith('data:') && !url.startsWith('#')) {
      const cleanPath = url.split('?')[0].split('#')[0];
      if (!fs.existsSync(cleanPath)) {
        missing.push({ type: 'link', path: cleanPath });
      }
    }
  }

  if (missing.length > 0) {
    results[file] = missing;
  }
});

console.log('Missing assets across HTML files:');
console.log(JSON.stringify(results, null, 2));
"

